{"path":"tools/LetUsCook.AutoWrongCensus/AutoWrongCensusCli.cs","content":"using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading.Tasks;

using LetUsCook.AutoWrongCensus.Services;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// F-428 P12.13 CLI entry point. Two subcommands, both read-only:
/// <c>census &lt;trace.jsonl&gt;</c> classifies every auto-wrong line of a HoldoutGate trace
/// (debug or batch only — D-029) by relation and site; <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>
/// emits the window compound/other head-word pairs for P12.18.
/// </summary>
public static class AutoWrongCensusCli
{
	private const string Usage = """
		usage:
		  LetUsCook.AutoWrongCensus census <trace.jsonl>
		  LetUsCook.AutoWrongCensus pairs <census.tsv> <trace.jsonl>
		""";

	public static async Task<int> RunAsync(string[] args)
	{
		if (args.Length == 1 && (args[0].Equals("--help", StringComparison.OrdinalIgnoreCase) || args[0].Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			Console.Error.WriteLine(Usage);
			return 0;
		}

		if (args.Length != 2 && args.Length != 3)
		{
			Console.Error.WriteLine(Usage);
			return 1;
		}

		var command = args[0];
		if (command.Equals("census", StringComparison.OrdinalIgnoreCase))
		{
			return await CensusCommand.RunAsync(args[1]).ConfigureAwait(false);
		}

		if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase) && args.Length == 3)
		{
			return await PairsCommand.RunAsync(args[1], args[2]).ConfigureAwait(false);
		}

		Console.Error.WriteLine(Usage);
		return 1;
	}

	private static readonly JsonSerializerOptions TraceJsonOptions = new(JsonSerializerDefaults.Web)
	{
		PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
		NumberHandling = JsonNumberHandling.AllowReadingFromString,
	};

	/// <summary>Reads a HoldoutGate trace file (the <c>--trace-file</c> JSONL of <c>tools/LetUsCook.HoldoutGate</c>).</summary>
	internal static async Task<IReadOnlyList<TraceLine>> ReadTraceAsync(string path)
	{
		var lines = new List<TraceLine>();
		await foreach (var line in File.ReadLinesAsync(path).ConfigureAwait(false))
		{
			if (line.Length == 0)
			{
				continue;
			}

			var record = JsonSerializer.Deserialize<TraceLine>(line, TraceJsonOptions);
			if (record is null)
			{
				throw new InvalidDataException($"Malformed trace record in '{path}': {line}");
			}

			lines.Add(record);
		}

		return lines;
	}

	/// <summary>One trace line, shaped like <c>tools/LetUsCook.HoldoutGate</c>'s <c>GateSweepReplay.TraceLine</c>.</summary>
	public sealed record TraceLine
	{
		public string RawText { get; init; } = string.Empty;

		public string HoldoutId { get; init; } = string.Empty;

		public int LineIndex { get; init; }

		[JsonConverter(typeof(JsonStringEnumConverter))]
		public Fdc.FdcDataset? ExpectedDataType { get; init; }

		[JsonConverter(typeof(JsonStringEnumConverter))]
		public Fdc.FdcDataset? ActualDataType { get; init; }

		public string Set { get; init; } = string.Empty;

		public bool Auto { get; init; }

		public bool Correct { get; init; }

		public IReadOnlyList<TraceAtom>? Atoms { get; init; }
	}

	/// <summary>One resolved atom of a trace line.</summary>
	public sealed record TraceAtom
	{
		public string Outcome { get; init; } = string.Empty;

		public string? LinkedIngredientId { get; init; }

		public string ParsedName { get; init; } = string.Empty;

		public int AcceptedIndex { get; init; }

		public bool Reused { get; init; }

		public string Path { get; init; } = string.Empty;
	}

	/// <summary>One classified auto-wrong line — the census TSV row.</summary>
	public sealed record CensusRow
	{
		public string HoldoutId { get; init; } = string.Empty;

		public int LineIndex { get; init; }

		public string Set { get; init; } = string.Empty;

		public string Relation { get; init; } = string.Empty;

		public string Site { get; init; } = string.Empty;

		public bool OverrideKey { get; init; }

		public string AcceptedTier { get; init; } = string.Empty;

		public string KeyTier { get; init; } = string.Empty;

		public string AcceptedState { get; init; } = string.Empty;

		public string KeyState { get; init; } = string.Empty;

		public string ParsedName { get; init; } = string.Empty;

		public string KeyHead { get; init; } = string.Empty;

		public string AcceptedDesc { get; init; } = string.Empty;

		public string KeyDesc { get; init; } = string.Empty;

		public string RawText { get; init; } = string.Empty;
	}

	/// <summary>Writes census rows as the TSV contract: one header, one row per auto-wrong line, tab-separated, no ANSI.</summary>
	public static void WriteTsv(IReadOnlyList<CensusRow> rows, TextWriter writer)
	{
		writer.WriteLine(string.Join('\t',
			"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey",
			"acceptedTier", "keyTier", "acceptedState", "keyState",
			"parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText"));

		foreach (var row in rows)
		{
			writer.WriteLine(string.Join('\t',
				row.HoldoutId, row.LineIndex, row.Set, row.Relation, row.Site, row.OverrideKey,
				row.AcceptedTier, row.KeyTier, row.AcceptedState, row.KeyState,
				row.ParsedName, row.KeyHead, row.AcceptedDesc, row.KeyDesc, row.RawText));
		}
	}

	/// <summary>The stderr summary: relation × site counts, plus the <c>other</c> share per the brief's 15 % falsifier.</summary>
	public static void WriteSummary(IReadOnlyList<CensusRow> rows, TextWriter writer)
	{
		var byRelation = new Dictionary<string, int>(StringComparer.Ordinal);
		var byRelationSite = new Dictionary<(string, string), int>(Comparer<(string, string)>.Default);
		var bySite = new Dictionary<string, int>(StringComparer.Ordinal);

		foreach (var row in rows)
		{
			byRelation[row.Relation] = byRelation.GetValueOrDefault(row.Relation) + 1;
			bySite[row.Site] = bySite.GetValueOrDefault(row.Site) + 1;
			var cell = (row.Relation, row.Site);
			byRelationSite[cell] = byRelationSite.GetValueOrDefault(cell) + 1;
		}

		writer.WriteLine($"auto-wrong lines: {rows.Count}");
		writer.WriteLine();
		writer.WriteLine("relation:");
		foreach (var (relation, count) in byRelation.OrderByDescending(kvp => kvp.Value).ThenBy(kvp => kvp.Key, StringComparer.Ordinal))
		{
			writer.WriteLine($"  {relation,-24} {count,4}");
		}

		writer.WriteLine();
		writer.WriteLine("site:");
		foreach (var (site, count) in bySite.OrderByDescending(kvp => kvp.Value).ThenBy(kvp => kvp.Key, StringComparer.Ordinal))
		{
			writer.WriteLine($"  {site,-24} {count,4}");
		}

		writer.WriteLine();
		writer.WriteLine("relation x site:");
		foreach (var ((relation, site), count) in byRelationSite.OrderByDescending(kvp => kvp.Value).ThenBy(kvp => kvp.Key, StringComparer.Ordinal))
		{
			writer.WriteLine($"  {relation,-24} {site,-12} {count,4}");
		}

		if (rows.Count > 0)
		{
			var other = byRelation.GetValueOrDefault(RelationClassifier.RelationOther) ?? 0;
			var pct = other * 100.0 / rows.Count;
			writer.WriteLine();
			writer.WriteLine($"other: {other}/{rows.Count} = {pct:0.0}% (falsified if > 15%)");
		}
	}
}
","i":"Writing CLI entry, DTOs, TSV and summary writers"}

{"path":"tools/LetUsCook.AutoWrongCensus/Options/CommandLineArgumentParser.cs","content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Maps the CLI argument list onto the <see cref="AutoWrongCensusOptions"/> configuration keys.
/// The census tool takes positional arguments (<c>census &lt;trace&gt;</c>,
/// <c>pairs &lt;census.tsv&gt; &lt;trace&gt;</c>), not <c>--key value</c> flags, so this is a
/// hand-rolled parser feeding <c>AddInMemoryCollection</c> — the stock command-line provider
/// would not bind positionals.
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>Parses the arguments into configuration keys.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <returns>
	/// The configuration mapping. An unusable invocation (no command, or a command with the wrong
	/// argument count) yields an empty dictionary; the runner then refuses with a usage line.
	/// </returns>
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);

		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);
		if (args.Length == 0)
		{
			return dict;
		}

		var command = args[0];
		if (command.Equals("census", StringComparison.OrdinalIgnoreCase))
		{
			if (args.Length < 2)
			{
				return dict;
			}

			dict[AutoWrongCensusOptions.SectionName + ":Command"] = "census";
			dict[AutoWrongCensusOptions.SectionName + ":TracePath"] = args[1];
		}
		else if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase))
		{
			if (args.Length < 3)
			{
				return dict;
			}

			dict[AutoWrongCensusOptions.SectionName + ":Command"] = "pairs";
			dict[AutoWrongCensusOptions.SectionName + ":CensusTsvPath"] = args[1];
			dict[AutoWrongCensusOptions.SectionName + ":TracePath"] = args[2];
		}
		else
		{
			return dict;
		}

		return dict;
	}
}
","i":"Writing argument parser"}

