{"path":"tools/LetUsCook.AutoWrongCensus/HostedServices/AutoWrongCensusHostBuilderFactory.cs","content":"using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.HostedServices;

/// <summary>
/// Builds the host graph for the auto-wrong census. The graph is deliberately thin — the tool classifies
/// a trace file and needs no FDC database, no HTTP, no content lookup — but it is the real host the CLI
/// runs, so the tests exercise this factory rather than a copy.
/// </summary>
public static class AutoWrongCensusHostBuilderFactory
{
	/// <summary>Creates the host builder for one invocation.</summary>
	/// <param name="args">Raw command-line arguments.</param>
	/// <param name="output">TSV sink; defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">Summary/diagnostics sink; defaults to <see cref="System.Console.Error"/>.</param>
	public static HostApplicationBuilder Create(string[] args, System.IO.TextWriter? output = null, System.IO.TextWriter? error = null)
	{
		ArgumentNullException.ThrowIfNull(args);

		var builder = Host.CreateApplicationBuilder();

		// The stock command-line provider understands only --key value; the positional subcommand
		// syntax is parsed explicitly and bound via an in-memory section.
		builder.Configuration.AddInMemoryCollection(CommandLineArgumentParser.Parse(args));
		builder.Services.Configure<AutoWrongCensusOptions>(builder.Configuration.GetSection(AutoWrongCensusOptions.SectionName));

		var debug = Array.Exists(args, a => a.Equals("--debug", StringComparison.OrdinalIgnoreCase) || a.Equals("--verbose", StringComparison.OrdinalIgnoreCase));
		builder.Logging.ClearProviders();
		builder.Logging.AddConsole();
		builder.Logging.SetMinimumLevel(debug ? LogLevel.Debug : LogLevel.Error);
		builder.Logging.AddFilter("Microsoft", LogLevel.Warning);

		builder.Services.AddSingleton(output ?? System.Console.Out);
		builder.Services.AddSingleton(error ?? System.Console.Error);
		builder.Services.AddSingleton<Services.IAutoWrongCensusRunner, Services.AutoWrongCensusRunner>();
		builder.Services.AddSingleton<AutoWrongCensusHostedService>();
		builder.Services.AddHostedService(sp => sp.GetRequiredService<AutoWrongCensusHostedService>());

		return builder;
	}
}
","i":"Writing host factory"}

{"path":"tools/LetUsCook.AutoWrongCensus/HostedServices/AutoWrongCensusHostedService.cs","content":"using System.Diagnostics.CodeAnalysis;

using LetUsCook.AutoWrongCensus.Services;

using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace LetUsCook.AutoWrongCensus.HostedServices;

/// <summary>
/// Runs the single census/pairs invocation, captures its exit code, and stops the host.
/// Fail-closed: 1 until the runner returns 0.
/// </summary>
public sealed class AutoWrongCensusHostedService(
	IAutoWrongCensusRunner runner,
	IHostApplicationLifetime lifetime,
	ILogger<AutoWrongCensusHostedService> logger) : BackgroundService
{
	/// <summary>The process exit code the CLI returns after the host shuts down.</summary>
	public int ExitCode { get; private set; } = 1;

	[SuppressMessage("Design", "CA1031:Do not catch general exception types", Justification = "Top-level CLI host exception handler")]
	protected override async Task ExecuteAsync(CancellationToken stoppingToken)
	{
		try
		{
			ExitCode = await runner.RunAsync(stoppingToken).ConfigureAwait(false);
		}
		catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
		{
			ExitCode = 1;
		}
		catch (Exception ex)
		{
			logger.LogError(ex, "Auto-wrong census runner failed.");
			ExitCode = 1;
		}
		finally
		{
			lifetime.StopApplication();
		}
	}
}
","i":"Writing hosted service"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies one auto-wrong trace line on two axes — the <em>relation</em> between the
/// accepted row and the labelled (key) row, and the <em>site</em> that accepted it.
/// <para>
/// Every comparison calls the production helpers (F-428 D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>
/// for tokenization, <see cref="FdcMatcher.ExtractCandidateState"/>/<see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
/// for the state masks, <see cref="FdcDescriptionParser.Parse"/> for the key's head,
/// <see cref="IngredientLineResolver.SingularizeToken"/> for singularising, and
/// <see cref="IngredientLineResolver.ShouldReuse"/> for the reuse-site check. Nothing here copies matcher logic.
/// </para>
/// </summary>
public sealed class AutoWrongClassifier
{
	private static readonly FdcNormalizer Normalizer = new();

	private static readonly FrozenSet<string> PackUnitWords =
		FrozenSet.ToFrozenSet(["can", "cans", "jar", "jars"], StringComparer.OrdinalIgnoreCase);

	private static readonly FrozenSet<string> PackUnitWordsWithUnit =
		FrozenSet.ToFrozenSet(["bottle", "bottles", "tin", "tins", "package", "packages", "pack", "pouch", "pouches"], StringComparer.OrdinalIgnoreCase);

	private static readonly FrozenSet<string> StateWords =
		FdcLexicon.Default.PreparationStates
			.Union(FdcLexicon.Default.UsdaStateQualifiers, StringComparer.OrdinalIgnoreCase)
			.ToFrozenSet(StringComparer.OrdinalIgnoreCase);

	private static readonly FrozenSet<string> ModifierWords = FdcLexicon.Default.ModifierWords;

	private static readonly FrozenSet<string> FoodHeads = FdcLexicon.Default.FoodHeads;

	private static readonly FrozenSet<string> PortionNouns = FdcLexicon.Default.PortionNouns;

	private static readonly FrozenSet<string> PhysicalParts = FdcLexicon.Default.PhysicalParts;

	private static readonly FrozenSet<string> EquipmentNouns = FdcLexicon.Default.EquipmentNouns;

	private static readonly FrozenSet<string> StopWords = FdcLexicon.Default.StopWords;

	private static readonly FrozenSet<string> FormWords = FdcLexicon.Default.FormWords;

	private static readonly FrozenSet<string> BrandNames = FdcLexicon.Default.BrandNames;

	private static readonly FrozenSet<string> KnownPhrases = FdcLexicon.Default.KnownPhrases.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins (brief §4 order 1–8);
	/// the site comes from the accepted atom's <c>path</c>/<c>reused</c> fields.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification, or <see langword="null"/> when the line has no accepted atom to classify.</returns>
	public AutoWrongClassification? Classify(TraceLine line)
	{
		var atom = AcceptedAtom(line);
		if (atom is null)
		{
			return null;
		}

		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var keyType = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var acceptedDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var acceptedType = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;

		var keyTokens = Normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = Normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = FdcMatcher.ExtractCandidateState(keyTokens);
		var keySatisfiers = FdcMatcher.ExtractCandidateSatisfiers(keyTokens);
		var acceptedState = FdcMatcher.ExtractCandidateState(acceptedTokens);
		var acceptedSatisfiers = FdcMatcher.ExtractCandidateSatisfiers(acceptedTokens);

		var keyHead = keyDesc.Length > 0 ? FdcDescriptionParser.Parse(keyDesc, ParseDataset(keyType)) : null;
		var acceptedHead = acceptedDesc.Length > 0 ? FdcDescriptionParser.Parse(acceptedDesc, ParseDataset(acceptedType)) : null;

		var keyHeadTokens = HeadTokens(keyHead);
		var acceptedHeadTokens = HeadTokens(acceptedHead);
		var parsedNameTokens = Normalizer.NormalizeToTokens(atom.ParsedName);

		var relation = ClassifyRelation(line, keyDesc, keyState, keySatisfiers, acceptedState, acceptedSatisfiers, keyHeadTokens, acceptedHeadTokens, parsedNameTokens);

		return new AutoWrongClassification(
			line.HoldoutId,
			line.LineIndex,
			line.Set,
			relation,
			ClassifySite(atom, line.RawText),
			OverrideKeyFor(line.RawText),
			acceptedType,
			keyType,
			FormatState(acceptedState, acceptedSatisfiers),
			FormatState(keyState, keySatisfiers),
			atom.ParsedName,
			keyHead?.HeadTerm ?? string.Empty,
			acceptedDesc,
			keyDesc,
			line.RawText);
	}

	/// <summary>
	/// The <c>pairs</c> subcommand's per-row output: the parsedName's head word and the key's head word(s),
	/// for a P12.7 <c>window</c> + compound/other row.
	/// </summary>
	public AutoWrongPair Pair(TraceLine line)
	{
		var atom = AcceptedAtom(line);
		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var keyType = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var keyHead = keyDesc.Length > 0 ? FdcDescriptionParser.Parse(keyDesc, ParseDataset(keyType)) : null;

		var parsedHead = string.Empty;
		if (atom is not null)
		{
			var parsedTokens = Normalizer.NormalizeToTokens(atom.ParsedName);
			parsedHead = parsedTokens.Count > 0 ? parsedTokens[^1] : string.Empty;
		}

		return new AutoWrongPair(
			line.HoldoutId,
			line.LineIndex,
			parsedHead,
			string.Join(' ', HeadTokens(keyHead)),
			line.RawText);
	}

	private static TraceAtom? AcceptedAtom(TraceLine line)
	{
		foreach (var atom in line.Atoms)
		{
			if (string.Equals(atom.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return null;
	}

	private string ClassifyRelation(
		TraceLine line,
		string keyDesc,
		FoodState keyState,
		FoodState keySatisfiers,
		FoodState acceptedState,
		FoodState acceptedSatisfiers,
		IReadOnlyList<string> keyHeadTokens,
		IReadOnlyList<string> acceptedHeadTokens,
		IReadOnlyList<string> parsedNameTokens)
	{
		// 1. no-label — the key is empty, so the row was accepted with nothing to compare against.
		if (keyDesc.Length == 0)
		{
			return "no-label";
		}

		var keyHasCanned = (keyState & FoodState.Canned) != FoodState.None || (keySatisfiers & FoodState.Canned) != FoodState.None;
		var acceptedHasCanned = (acceptedState & FoodState.Canned) != FoodState.None || (acceptedSatisfiers & FoodState.Canned) != FoodState.None;

		// 2. pack-unit-state — the raw line names a can/jar unit, the key row is canned, the accepted row is not.
		if (HasPackUnit(line.RawText) && keyHasCanned && !acceptedHasCanned)
		{
			return "pack-unit-state";
		}

		// 3. compound-head-lost — the key's head is a multi-word phrase, the parsedName is only its first word,
		// and the key's head is not a category header (a header's first word is a class noun, not the food).
		if (keyHeadTokens.Count >= 2 && !IsCategoryHeader(keyHeadTokens[0]) && parsedNameTokens.Count > 0)
		{
			var firstWord = Singularize(keyHeadTokens[0]);
			if (parsedNameTokens.Count == 1
				&& string.Equals(Singularize(parsedNameTokens[0]), firstWord, StringComparison.OrdinalIgnoreCase))
			{
				return "compound-head-lost";
			}
		}

		var keyHeadSet = keyHeadTokens.ToHashSet(StringComparer.OrdinalIgnoreCase);
		var acceptedHeadSet = acceptedHeadTokens.ToHashSet(StringComparer.OrdinalIgnoreCase);
		var headsAgree = keyHeadSet.Count > 0 && acceptedHeadSet.Count > 0 && keyHeadSet.SetEquals(acceptedHeadSet);
		var statesAgree = keyState == acceptedState && keySatisfiers == acceptedSatisfiers;

		// 4. state-mismatch — the heads agree, the state masks differ.
		if (headsAgree && !statesAgree)
		{
			return "state-mismatch";
		}

		// 5. row-choice-tier — heads and state agree, the dataset tier differs.
		if (headsAgree && statesAgree && !string.Equals(line.ExpectedDataTypes.FirstOrDefault(), line.ActualDataTypes.FirstOrDefault(), StringComparison.OrdinalIgnoreCase))
		{
			return "row-choice-tier";
		}

		// 6. same-head-other-qualifier — heads agree, nothing above holds.
		if (headsAgree)
		{
			return "same-head-other-qualifier";
		}

		// 7. sibling-food — the heads differ.
		if (keyHeadTokens.Count > 0 && acceptedHeadTokens.Count > 0)
		{
			return "sibling-food";
		}

		// 8. other — the head is unparseable on one side; the line is classified on the site axis only.
		return "other";
	}

	private string ClassifySite(TraceAtom atom, string rawText)
	{
		if (atom.Reused && string.Equals(atom.Path, "ranker", StringComparison.OrdinalIgnoreCase))
		{
			return "reuse";
		}

		if (string.Equals(atom.Path, "override", StringComparison.OrdinalIgnoreCase))
		{
			return "override";
		}

		if (string.Equals(atom.Path, "curated", StringComparison.OrdinalIgnoreCase))
		{
			return "curated";
		}

		return "ranker";
	}

	/// <summary>
	/// The production override lookup key for the raw text: strip from the first parenthesis, trim,
	/// lowercase — the same cleaning <c>FdcMatcher.MatchAsync</c> applies before
	/// <c>SpecialCases.TryGetRaw</c>.
	/// </summary>
	private static string OverrideKeyFor(string rawText)
	{
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = index >= 0 ? rawText[..index] : rawText;
#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override lookup key.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	/// <summary>
	/// Whether the raw line names a pack unit: <c>can</c>/<c>cans</c>/<c>jar</c>/<c>jars</c> (any amount),
	/// or another container word carrying a quantity unit.
	/// </summary>
	private static bool HasPackUnit(string rawText)
	{
		var tokens = Normalizer.NormalizeToTokens(rawText);
		for (var i = 0; i < tokens.Count; i++)
		{
			if (PackUnitWords.Contains(tokens[i]))
			{
				return true;
			}

			if (PackUnitWordsWithUnit.Contains(tokens[i]))
			{
				for (var j = i + 1; j < tokens.Count; j++)
				{
					if (IsQuantityUnit(tokens[j]))
					{
						return true;
					}

					if (!IsQuantityModifier(tokens[j]))
					{
						break;
					}
				}
			}
		}

		return false;
	}

	private static bool IsQuantityUnit(string token) =>
		token is "ounce" or "ounces" or "oz" or "pound" or "pounds" or "lb" or "lbs" or "gram" or "grams" or "g" or "ml" or "milliliter" or "milliliters";

	private static bool IsQuantityModifier(string token) =>
		token is "of" or "and" or "or" or "drained" or "diced" or "chopped" or "sliced" or "whole" or "small" or "large" or "medium";

	/// <summary>
	/// The head phrase of a parsed FDC description: the head term plus any adjacent leading qualifier
	/// that is a state or preparation word — the multi-word head the parser's single-token
	/// <c>HeadTerm</c> cannot express ("crushed tomato" in "Tomatoes, crushed, canned").
	/// </summary>
	private static IReadOnlyList<string> HeadTokens(ParsedFdcDescription? parsed)
	{
		if (parsed is null || parsed.HeadTerm.Length == 0)
		{
			return [];
		}

		var tokens = new List<string>();
		var qualifiers = parsed.Qualifiers;
		for (var i = 0; i < qualifiers.Count; i++)
		{
			var token = qualifiers[i];
			if (StateWords.Contains(token) || ModifierWords.Contains(token))
			{
				tokens.Add(token);
			}
			else
			{
				break;
			}
		}

		tokens.Add(parsed.HeadTerm);
		return tokens;
	}

	private static bool IsCategoryHeader(string token)
	{
		if (FoodHeads.Contains(token))
		{
			return false;
		}

		return token is "spice" or "spices" or "seasoning" or "seasonings" or "oil" or "oils" or "cheese" or "cheeses"
			or "nut" or "nuts" or "seed" or "seeds" or "beverage" or "beverages" or "fish"
			or "mollusk" or "mollusks" or "crustacean" or "crustaceans" or "leavening" or "agent" or "agents";
	}

	private static FdcDataset ParseDataset(string dataType) => dataType switch
	{
		"Foundation" => FdcDataset.Foundation,
		"SrLegacy" => FdcDataset.SrLegacy,
		"Survey" => FdcDataset.Survey,
		"Branded" => FdcDataset.Branded,
		_ => FdcDataset.None,
	};

	private static string Singularize(string token) => IngredientLineResolver.SingularizeToken(token);

	private static string FormatState(FoodState state, FoodState satisfiers)
	{
		var parts = new List<string>();
		foreach (FoodState flag in Enum.GetValues<FoodState>())
		{
			if (flag != FoodState.None && (state | satisfiers) == flag)
			{
				parts.Add(flag.ToString());
			}
		}

		return parts.Count > 0 ? string.Join('|', parts) : "none";
	}
}

/// <summary>One classified auto-wrong line — the census TSV row.</summary>
public sealed record AutoWrongClassification(
	string HoldoutId,
	int LineIndex,
	string Set,
	string Relation,
	string Site,
	string OverrideKey,
	string AcceptedTier,
	string KeyTier,
	string AcceptedState,
	string KeyState,
	string ParsedName,
	string KeyHead,
	string AcceptedDesc,
	string KeyDesc,
	string RawText);

/// <summary>One <c>pairs</c> output row.</summary>
public sealed record AutoWrongPair(
	string HoldoutId,
	int LineIndex,
	string ParsedNameHead,
	string KeyHead,
