{"path":"tools/LetUsCook.AutoWrongCensus/Services/CensusClassifier.cs","content":"using System.Text.Json;
using System.Text.Json.Serialization;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines — <em>relation</em>
/// (accepted row vs key row) and <em>site</em> (decision path) — calling the production helpers
/// (<c>FdcNormalizer</c>, <c>FdcDescriptionParser</c>, <c>FdcMatcher.ExtractCandidateState/
/// ExtractCandidateSatisfiers</c>, <c>IngredientLineResolver.SingularizeToken</c>) rather than copying
/// their logic (D-014).
/// </summary>
public static class CensusClassifier
{
	private static readonly FdcNormalizer Normalizer = new();

	/// <summary>
	/// Production state/modifier vocabulary: the 12 <c>FoodState</c> words plus the lexicon's
	/// <c>preparation-states.json</c> and <c>modifier-words.json</c> sets, all lower-cased. A head
	/// phrase is "cut at the first of these", so a compound head ("bread crumbs") is recovered even
	/// though <c>FdcDescriptionParser.HeadTerm</c> is a single token.
	/// </summary>
	private static readonly FrozenSet<string> StateModifierWords = BuildStateModifierWords();

	/// <summary>
	/// The relation classes, in the brief's precedence order. The first that holds wins; <c>other</c>
	/// is the residual.
	/// </summary>
	public static readonly string[] RelationClasses =
	[
		"no-label",
		"pack-unit-state",
		"compound-head-lost",
		"state-mismatch",
		"row-choice-tier",
		"same-head-other-qualifier",
		"sibling-food",
		"other"
	];

	private static readonly FrozenSet<string> PackUnitWords =
		FrozenSet.ToFrozenSet(["can", "cans", "jar", "jars"], StringComparer.OrdinalIgnoreCase);

	private static FrozenSet<string> BuildStateModifierWords()
	{
		var words = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var name in Enum.GetNames<FdcMatcher.FoodState>())
		{
			words.Add(name.ToLowerInvariant());
		}

		words.UnionWith(FdcLexicon.Default.PreparationStates);
		words.UnionWith(FdcLexicon.Default.ModifierWords);
		return words.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>
	/// Classifies one auto-wrong line. Never throws on a malformed line: missing fields degrade the
	/// line to <c>other</c> and are named in <see cref="ClassificationResult.MissingField"/>.
	/// </summary>
	/// <param name="line">The auto-wrong trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; the caller filters by <see cref="ClassificationResult.Relation"/>.</returns>
	public static ClassificationResult Classify(TraceLine line)
	{
		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var acceptedDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var keyTier = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var acceptedTier = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = ClassifySite(line, atom);
		var overrideKey = site == "override" ? (ExactOverrides.HasKey(line.RawText) ? "yes" : "no") : string.Empty;

		var keyHead = HeadPhrase(keyDesc);
		var keyTokens = new List<string>(Normalizer.NormalizeToTokens(keyDesc));
		var acceptedTokens = new List<string>(Normalizer.NormalizeToTokens(acceptedDesc));
		var keyState = MaskOf(keyTokens);
		var acceptedState = MaskOf(acceptedTokens);

		var missingField = (string?)null;
		if (line.ExpectedDescriptions.Count == 0)
		{
			missingField = "expectedDescriptions";
		}
		else if (line.ExpectedDataTypes.Count == 0 || string.IsNullOrWhiteSpace(line.ExpectedDataTypes[0]))
		{
			missingField = "expectedDataTypes";
		}
		else if (line.ActualDescriptions.Count == 0 || string.IsNullOrWhiteSpace(line.ActualDescriptions[0]))
		{
			missingField = "actualDescriptions";
		}
		else if (line.ActualDataTypes.Count == 0 || string.IsNullOrWhiteSpace(line.ActualDataTypes[0]))
		{
			missingField = "actualDataTypes";
		}

		var relation = ClassifyRelation(
			line.RawText,
			parsedName,
			keyDesc,
			acceptedDesc,
			keyTier,
			acceptedTier,
			keyState,
			acceptedState,
			keyHead,
			keyTokens,
			acceptedTokens,
			out var keyOnlyQualifiers,
			out var acceptedOnlyQualifiers);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = FormatMask(acceptedState),
			KeyState = FormatMask(keyState),
			ParsedName = parsedName,
			KeyHead = keyHead,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers
		};
	}

	/// <summary>
	/// The relation ladder (brief §4): the first class that holds wins.
	/// </summary>
	private static string ClassifyRelation(
		string rawText,
		string parsedName,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FdcMatcher.FoodState keyState,
		FdcMatcher.FoodState acceptedState,
		string keyHead,
		List<string> keyTokens,
		List<string> acceptedTokens,
		out IReadOnlyList<string>? keyOnlyQualifiers,
		out IReadOnlyList<string>? acceptedOnlyQualifiers)
	{
		keyOnlyQualifiers = null;
		acceptedOnlyQualifiers = null;

		// 1. no-label — expected empty.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return "no-label";
		}

		var keyHeadTokens = HeadTokens(keyDesc);
		var parsedTokens = Normalizer.NormalizeToTokens(parsedName);

		// 2. pack-unit-state — rawText carries a can/jar unit; the key's state has Canned, the accepted row's does not.
		if (HasPackUnit(rawText)
			&& (keyState & FdcMatcher.FoodState.Canned) != 0
			&& (acceptedState & FdcMatcher.FoodState.Canned) == 0)
		{
			return "pack-unit-state";
		}

		// 3. compound-head-lost — the key head phrase has two or more words and parsedName equals only
		//    its first word, after singularising.
		if (keyHeadTokens.Count >= 2
			&& parsedTokens.Count == 1
			&& string.Equals(
				IngredientLineResolver.SingularizeToken(parsedTokens[0]),
				IngredientLineResolver.SingularizeToken(keyHeadTokens[0]),
				StringComparer.OrdinalIgnoreCase))
		{
			return "compound-head-lost";
		}

		// 4. state-mismatch — the head phrases agree after singularising and the FoodState masks differ.
		if (HeadAgrees(keyHeadTokens, parsedTokens))
		{
			if (keyState != acceptedState)
			{
				return "state-mismatch";
			}

			// 5. row-choice-tier — head and state agree and the dataType tier differs.
			if (TierRank(keyTier) != TierRank(acceptedTier))
			{
				return "row-choice-tier";
			}

			// 6. same-head-other-qualifier — head agrees and nothing above holds.
			keyOnlyQualifiers = QualifierDiff(keyTokens, acceptedTokens);
			acceptedOnlyQualifiers = QualifierDiff(acceptedTokens, keyTokens);
			return "same-head-other-qualifier";
		}

		// 7. sibling-food — the head phrases differ.
		return "sibling-food";
	}

	/// <summary>
	/// The site (brief §4): <c>reuse</c> (reused, path ranker), <c>override</c>, <c>curated</c>,
	/// <c>ranker</c> (not reused). Empty when the atom path is unknown.
	/// </summary>
	private static string ClassifySite(TraceLine line, TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		if (atom.Reused && atom.Path == "ranker")
		{
			return "reuse";
		}

		return atom.Path switch
		{
			"override" => "override",
			"curated" => "curated",
			"ranker" => "ranker",
			_ => string.Empty
		};
	}

	/// <summary>
	/// The head phrase of an FDC description: the head segment's normalized tokens up to (not
	/// including) the first production state/modifier word. "Bread, crumbs, dry, grated, plain" →
	/// "bread crumbs"; "Nuts, almonds, blanched" → "almonds"; "Bread, white, commercially prepared
	/// (includes soft bread crumbs)" → "bread white".
	/// </summary>
	/// <param name="description">The FDC description.</param>
	/// <returns>The head phrase, space-joined; empty when the description is empty.</returns>
	public static string HeadPhrase(string description)
	{
		if (string.IsNullOrWhiteSpace(description))
		{
			return string.Empty;
		}

		var segments = description.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
		if (segments.Length == 0)
		{
			return string.Empty;
		}

		var tokens = Normalizer.NormalizeToTokens(segments[0]);
		var head = new List<string>();
		foreach (var token in tokens)
		{
			if (StateModifierWords.Contains(token))
			{
				break;
			}

			head.Add(token);
		}

		return string.Join(' ', head);
	}

	/// <summary>The head segment's normalized tokens (before the first state/modifier word).</summary>
	private static List<string> HeadTokens(string description)
	{
		if (string.IsNullOrWhiteSpace(description))
		{
			return [];
		}

		var segments = description.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
		var tokens = Normalizer.NormalizeToTokens(segments[0]);
		var head = new List<string>();
		foreach (var token in tokens)
		{
			if (StateModifierWords.Contains(token))
			{
				break;
			}

			head.Add(token);
		}

		return head;
	}

	/// <summary>
	/// The head phrases agree after singularising: same token count, each token equal to its
	/// counterpart via the resolver's own <see cref="IngredientLineResolver.SingularizeToken"/>.
	/// </summary>
	private static bool HeadAgrees(List<string> keyHeadTokens, IReadOnlyList<string> parsedTokens)
	{
		if (keyHeadTokens.Count == 0 || keyHeadTokens.Count != parsedTokens.Count)
		{
			return false;
		}

		for (var i = 0; i < keyHeadTokens.Count; i++)
		{
			if (!string.Equals(
				IngredientLineResolver.SingularizeToken(keyHeadTokens[i]),
				IngredientLineResolver.SingularizeToken(parsedTokens[i]),
				StringComparer.OrdinalIgnoreCase))
			{
				return false;
			}
		}

		return true;
	}

	/// <summary>
	/// The production state mask for a description: <c>ExtractCandidateState</c> ∪
	/// <c>ExtractCandidateSatisfiers</c> over its normalized tokens — the same composition the
	/// matcher applies to a candidate row.
	/// </summary>
	private static FdcMatcher.FoodState MaskOf(IReadOnlyList<string> tokens)
	{
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	/// <summary>Formats a state mask as comma-joined flag names, or <c>none</c>.</summary>
	public static string FormatMask(FdcMatcher.FoodState mask)
	{
		if (mask == FdcMatcher.FoodState.None)
		{
			return "none";
		}

		return string.Join(',', Enum.GetNames<FdcMatcher.FoodState>()
			.Where(n => (mask & (FdcMatcher.FoodState)Enum.Parse<FdcMatcher.FoodState>(n)) != 0));
	}

	/// <summary>The tier rank for row-choice-tier comparisons: Foundation &gt; SrLegacy &gt; Survey &gt; Branded.</summary>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 0,
		"SrLegacy" => 1,
		"Survey" => 2,
		"Branded" => 3,
		_ => int.MaxValue
	};

	/// <summary>Whether the raw line text carries a can/jar unit (a bare word or a parenthesized "(N ounce) can").</summary>
	public static bool HasPackUnit(string rawText)
	{
		if (string.IsNullOrWhiteSpace(rawText))
		{
			return false;
		}

		var tokens = Normalizer.NormalizeToTokens(rawText);
		for (var i = 0; i < tokens.Count; i++)
		{
			if (PackUnitWords.Contains(tokens[i]))
			{
				return true;
			}
		}

		return false;
	}

	/// <summary>
	/// The normalized tokens of <paramref name="a"/> absent from <paramref name="b"/> (case-insensitive,
	/// order-preserving) — the qualifier difference recorded on <c>same-head-other-qualifier</c> lines.
	/// </summary>
	private static IReadOnlyList<string> QualifierDiff(List<string> a, List<string> b)
	{
		var present = new HashSet<string>(b, StringComparer.OrdinalIgnoreCase);
		return a.Where(t => !present.Contains(t)).ToList();
	}

	/// <summary>
	/// Reads <c>Lexicon/Resources/exact-overrides.json</c> from the <c>LetUsCook.Fdc</c> assembly
	/// (embedded) once. The brief's overrideKey column asks whether the normalized rawText is a key in
	/// that file; the production runtime lookup goes through the unified <c>special-cases.json</c>
	/// (F-428 P6.3), which is noted in the report.
	/// </summary>
	private static readonly Lazy<FrozenSet<string>> ExactOverrideKeys = new(LoadExactOverrideKeys);

	private static FrozenSet<string> LoadExactOverrideKeys()
	{
		var assembly = typeof(FdcMatcher).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), new JsonSerializerOptions(JsonSerializerDefaults.Web))
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		return entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Whether the normalized rawText is a key in <c>exact-overrides.json</c>.</summary>
	public static bool ExactOverridesHasKey(string rawText)
	{
		if (string.IsNullOrWhiteSpace(rawText))
		{
			return false;
		}

#pragma warning disable CA1308 // Reason: parity with FdcMatcher's lowercase override lookup.
		var cleaned = rawText.Trim().ToLowerInvariant();
#pragma warning restore CA1308
		return ExactOverrideKeys.Value.Contains(cleaned);
	}
}
