{"path":"tools/LetUsCook.AutoWrongCensus/Services/TsvWriter.cs","content":"using System.Text;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The TSV the <c>census</c> subcommand prints: the brief's column contract, one auto-wrong line per row.
/// </summary>
public static class TsvWriter
{
	private static readonly string[] Columns =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey", "acceptedTier", "keyTier",
		"acceptedState", "keyState", "parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText"
	];

	/// <summary>Header row.</summary>
	public static string Header => string.Join('\t', Columns);

	/// <summary>One result row, in the brief's column order.</summary>
	/// <param name="result">The classification.</param>
	/// <returns>The TSV row without a trailing newline.</returns>
	public static string Row(ClassificationResult result)
	{
		var qualifierNote = string.Empty;
		if (result.KeyOnlyQualifiers is not null || result.AcceptedOnlyQualifiers is not null)
		{
			qualifierNote = " keyOnly=" + string.Join(",", result.KeyOnlyQualifiers ?? []);
			qualifierNote += " acceptedOnly=" + string.Join(",", result.AcceptedOnlyQualifiers ?? []);
		}

		return string.Join('\t',
			Escape(result.HoldoutId),
			result.LineIndex.ToString(),
			Escape(result.Set),
			Escape(result.Relation),
			Escape(result.Site),
			Escape(result.OverrideKey),
			Escape(result.AcceptedTier),
			Escape(result.KeyTier),
			Escape(result.AcceptedState),
			Escape(result.KeyState),
			Escape(result.ParsedName),
			Escape(result.KeyHead),
			Escape(result.AcceptedDesc + qualifierNote),
			Escape(result.KeyDesc),
			Escape(result.RawText));
	}

	/// <summary>Folds TSV-breaking characters to spaces.</summary>
	/// <param name="value">The cell value.</param>
	/// <returns>A tab/newline-safe rendering.</returns>
	private static string Escape(string value)
	{
		if (value.Length == 0)
		{
			return value;
		}

		var builder = new StringBuilder(value.Length);
		foreach (var c in value)
		{
			builder.Append(c is '\t' or '\n' or '\r' ? ' ' : c);
		}

		return builder.ToString();
	}
}
"}

{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongCensusClassifier.cs","content":"using System.Text;
using System.Text.RegularExpressions;

using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// F-428 P12.13: classifies every auto-wrong line of a debug/batch trace on two axes —
/// <see cref="Classify"/> (relation of the accepted row to the key row × decision site) and
/// <see cref="WindowPairs"/> (the P12.7 window compound/other head pairs P12.18 needs).
/// <para>
/// Every matcher-side value comes from the production helpers (F-428 D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens(string)"/>,
/// <see cref="FdcMatcher.ExtractCandidateState(System.Collections.Generic.IReadOnlyList{string})"/> and
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(System.Collections.Generic.IReadOnlyList{string})"/>,
/// <see cref="FdcDescriptionParser.Parse"/> and <see cref="IngredientLineResolver.SingularizeToken"/> —
/// never a re-implementation.
/// </para>
/// </summary>
public sealed class AutoWrongCensusClassifier
{
	/// <summary>Relation: no labelled row.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit line whose key row is canned and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is longer than the parsed name's head words.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: same head, different state masks.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: same head and state, different dataset tier.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: same head, nothing above holds; the qualifier sets differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the heads differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a required trace field was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the override path decided the row.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue decided the row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked a fresh row.</summary>
	public const string SiteRanker = "ranker";

	private static readonly FdcNormalizer Normalizer = new();

	private static readonly FdcDataset[] TierOrder =
	[
		FdcDataset.Foundation,
		FdcDataset.SrLegacy,
		FdcDataset.Survey,
		FdcDataset.Branded
	];

	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Creates the classifier.</summary>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key index.</param>
	public AutoWrongCensusClassifier(ExactOverrideKeyIndex overrideKeys)
	{
		_overrideKeys = overrideKeys;
	}

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins, in the brief's order:
	/// no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier,
	/// same-head-other-qualifier, sibling-food, other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.MissingField"/> names a trace field a check needed but did not find.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = ClassifySite(atom);

		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var keyTier = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var acceptedDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var acceptedTier = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;

		var keyTokens = Normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = Normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = StateMask(keyTokens);
		var acceptedState = StateMask(acceptedTokens);

		var keyHead = KeyHeadPhrase(keyTokens);
		var parsedHead = HeadWords(parsedName);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = FormatMask(acceptedState),
			KeyState = FormatMask(keyState),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHead),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText
		};

		if (site.Length == 0)
		{
			// Unknown atom path: the site axis is empty, and no relation is claimed (brief §4).
			result.Relation = Other;
			return result;
		}

		if (site == SiteOverride)
		{
			result.OverrideKey = _overrideKeys.IsKey(FoldForOverrideLookup(line.RawText)) ? "yes" : "no";
		}

		if (keyDesc.Length == 0)
		{
			result.Relation = NoLabel;
			return result;
		}

		if (acceptedDesc.Length == 0)
		{
			result.Relation = Other;
			result.MissingField = "actualDescriptions";
			return result;
		}

		if (IsPackUnit(line.RawText) && keyState.HasFlag(FoodState.Canned) && !acceptedState.HasFlag(FoodState.Canned))
		{
			result.Relation = PackUnitState;
			return result;
		}

		if (keyHead.Count >= 2 && parsedHead.Count > 0 && parsedHead.Count < keyHead.Count
			&& parsedHead.SequenceEqual(keyHead.Take(parsedHead.Count), StringComparer.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		var headsAgree = HeadsAgree(keyHead, parsedHead);
		if (headsAgree && keyState != acceptedState)
		{
			result.Relation = StateMismatch;
			return result;
		}

		if (headsAgree && keyState == acceptedState && !string.Equals(acceptedTier, keyTier, StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = RowChoiceTier;
			return result;
		}

		if (headsAgree && keyState == acceptedState && string.Equals(acceptedTier, keyTier, StringComparison.OrdinalIgnoreCase))
		{
			var keyQualifiers = QualifierTokens(keyTokens, keyHead);
			var acceptedQualifiers = QualifierTokens(acceptedTokens, parsedHead);
			var keyOnly = keyQualifiers.Where(q => !acceptedQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).ToList();
			var acceptedOnly = acceptedQualifiers.Where(q => !keyQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).ToList();
			if (keyOnly.Count == 0 && acceptedOnly.Count == 0)
			{
				result.Relation = Other;
			}
			else
			{
				result.Relation = SameHeadOtherQualifier;
				result.KeyOnlyQualifiers = keyOnly;
				result.AcceptedOnlyQualifiers = acceptedOnly;
			}

			return result;
		}

		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// The <c>pairs</c> subcommand: for every P12.7 blocker-census row with <c>blocker == window</c> and
	/// <c>route</c> compound or other, the parsedName head words and the key head phrase from the trace.
	/// </summary>
	/// <param name="censusTsv">The P12.7 blocker-census TSV (header: holdoutId lineIndex … blocker … route …).</param>
	/// <param name="trace">The trace to join against.</param>
	/// <returns>One row per matching census row: holdoutId, lineIndex, parsedName head, key head, rawText.</returns>
	public IReadOnlyList<string[]> WindowPairs(string censusTsv, TraceLine[] trace)
	{
		var byKey = new Dictionary<(string, int), TraceLine>(trace.ToDictionary(l => (l.HoldoutId, l.LineIndex)));

		var rows = new List<string[]>();
		foreach (var fields in ParseTsv(censusTsv))
		{
			if (fields.Length < 2)
			{
				continue;
			}

			var blocker = IndexOf(fields, "blocker");
			var route = IndexOf(fields, "route");
			if (blocker < 0 || route < 0 || fields[blocker] != "window" || (fields[route] != "compound" && fields[route] != "other"))
			{
				continue;
			}

			var lineIndex = int.TryParse(fields[1], out var li) ? li : -1;
			if (lineIndex < 0 || !byKey.TryGetValue((fields[0], lineIndex), out var line))
			{
				// The census and the trace disagree (different trees); emit the row with empty trace fields.
				rows.Add([fields[0], fields[1], string.Empty, string.Empty, string.Empty]);
				continue;
			}

			var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
			var keyTokens = Normalizer.NormalizeToTokens(line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty);
			rows.Add([fields[0], fields[1], string.Join(' ', HeadWords(atom?.ParsedName ?? string.Empty)), string.Join(' ', KeyHeadPhrase(keyTokens)), line.RawText]);
		}

		return rows;
	}

	/// <summary>The decision site from the atom's path and reuse flag.</summary>
	/// <param name="atom">The accepted atom, or null when the line has none.</param>
	/// <returns>One of <see cref="SiteReuse"/>, <see cref="SiteOverride"/>, <see cref="SiteCurated"/>, <see cref="SiteRanker"/>; empty when the path is unknown.</returns>
	public static string ClassifySite(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		if (atom.Path.Equals("override", StringComparison.OrdinalIgnoreCase))
		{
			return SiteOverride;
		}

		if (atom.Path.Equals("curated", StringComparison.OrdinalIgnoreCase))
		{
			return SiteCurated;
		}

		if (atom.Path.Equals("ranker", StringComparison.OrdinalIgnoreCase))
		{
			return atom.Reused ? SiteReuse : SiteRanker;
		}

		return string.Empty;
	}

	/// <summary>
	/// The head phrase of a description: the head tokens up to the first production state/modifier
	/// word (the <c>preparation-states.json</c> ∪ <c>modifier-words.json</c> lexicon sets, plus the
	/// <see cref="FdcMatcher.ExtractCandidateState(System.Collections.Generic.IReadOnlyList{string})"/>
	/// state words). "Bread, crumbs, dry, grated, plain" → "bread crumbs"; "Nuts, almonds, blanched"
	/// → "almonds".
	/// </summary>
	/// <param name="headTokens">The first segment's normalized tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public static IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> headTokens)
	{
		var stateWords = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var word in FdcLexicon.Default.PreparationStates)
		{
			stateWords.Add(word);
		}

		foreach (var word in FdcLexicon.Default.ModifierWords)
		{
			stateWords.Add(word);
		}

		foreach (var flag in (FoodState[])Enum.GetValues(typeof(FoodState)))
		{
			if (flag != FoodState.None)
			{
				stateWords.Add(flag.ToString().ToLowerInvariant());
			}
		}

		var head = new List<string>();
		foreach (var token in headTokens)
		{
			if (stateWords.Contains(token))
			{
				break;
			}

			head.Add(token);
		}

		return head;
	}

	/// <summary>
	/// The head words of a parsed name: the normalized tokens up to the first production state/modifier
	/// word, each singularised with <see cref="IngredientLineResolver.SingularizeToken"/>.
	/// </summary>
	/// <param name="parsedName">The parser's name for the atom.</param>
	/// <returns>The singularised head words.</returns>
	public static IReadOnlyList<string> HeadWords(string parsedName)
	{
		var tokens = Normalizer.NormalizeToTokens(parsedName);
		var stateWords = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var word in FdcLexicon.Default.PreparationStates)
		{
			stateWords.Add(word);
		}

		foreach (var word in FdcLexicon.Default.ModifierWords)
		{
			stateWords.Add(word);
		}

		foreach (var flag in (FoodState[])Enum.GetValues(typeof(FoodState)))
		{
			if (flag != FoodState.None)
			{
				stateWords.Add(flag.ToString().ToLowerInvariant());
			}
		}

		var head = new List<string>();
		foreach (var token in tokens)
		{
			if (stateWords.Contains(token))
			{
				break;
			}

			head.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return head;
	}

	/// <summary>The relation-3/4/5/6/7 head comparison: singularised, ordinal-ignore-case, order-sensitive.</summary>
	/// <param name="keyHead">The key head phrase tokens.</param>
	/// <param name="parsedHead">The parsed name's head words.</param>
	/// <returns>Whether the two head word sequences agree.</returns>
	public static bool HeadsAgree(IReadOnlyList<string> keyHead, IReadOnlyList<string> parsedHead)
		=> keyHead.SequenceEqual(parsedHead, StringComparer.OrdinalIgnoreCase);

	/// <summary>
	/// Whether the raw line names a can or jar unit: a <c>can</c>/<c>cans</c>/<c>jar</c> word, or a
	/// parenthetical can form like <c>(28 ounce) can</c>.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>Whether a can/jar unit is present.</returns>
	public static bool IsPackUnit(string rawText)
	{
		if (PackUnitRegex().IsMatch(rawText))
		{
			return true;
		}

		return ParenCanRegex().IsMatch(rawText);
	}

	/// <summary>
	/// The raw line text folded the way the override lookup folds it: lower-cased, trimmed, content
	/// from the first <c>(</c> dropped (parity with <c>FdcMatcher</c>'s <c>StripFromParenthesis</c> +
	/// <c>ToLowerInvariant</c>; the embedded key set is all-lowercase, so the fold is exact).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string FoldForOverrideLookup(string rawText)
	{
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = index >= 0 ? rawText[..index] : rawText;
#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override lookup fold.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	/// <summary>The <see cref="FoodState"/> mask of a description: state ∪ satisfiers, both production passes.</summary>
	/// <param name="tokens">The description's normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState StateMask(IReadOnlyList<string> tokens)
		=> FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Formats a <see cref="FoodState"/> mask as its flag names, or <c>none</c>.</summary>
	/// <param name="mask">The mask to format.</param>
	/// <returns>The comma-joined flag names.</returns>
	public static string FormatMask(FoodState mask)
	{
		if (mask == FoodState.None)
		{
			return "none";
		}

		var names = (FoodState[])Enum.GetValues(typeof(FoodState))
			.Where(flag => flag != FoodState.None && mask.HasFlag(flag))
			.Select(flag => flag.ToString());
		return string.Join(',', names);
	}

	/// <summary>The qualifier tokens of a description: all tokens minus the head phrase tokens.</summary>
	/// <param name="tokens">The description's normalized tokens.</param>
	/// <param name="headTokens">The head phrase tokens.</param>
	/// <returns>The remaining tokens.</returns>
	public static IReadOnlyList<string> QualifierTokens(IReadOnlyList<string> tokens, IReadOnlyList<string> headTokens)
	{
		var head = new HashSet<string>(headTokens, StringComparer.OrdinalIgnoreCase);
		return tokens.Where(t => !head.Contains(t)).ToList();
	}

	/// <summary>Parses a TSV into rows of fields (header row included).</summary>
	/// <param name="tsv">The TSV text.</param>
	/// <returns>The rows.</returns>
	public static IReadOnlyList<string[]> ParseTsv(string tsv)
	{
		var rows = new List<string[]>();
		foreach (var line in tsv.Split('\n'))
		{
			var trimmed = line.TrimEnd('\r');
			if (trimmed.Length == 0)
			{
				continue;
			}

			rows.Add(trimmed.Split('\t'));
		}

		return rows;
	}

	private static int IndexOf(string[] fields, string name)
	{
		for (var i = 0; i < fields.Length; i++)
		{
			if (fields[i] == name)
			{
				return i;
			}
		}

		return -1;
	}

	[GeneratedRegex(@"\bcan(s)?\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	[GeneratedRegex(@"\(\s*\d+(?:\.\d+)?\s*(?:ounce|oz|gram|g|pound|lb|ml|millilitre)\s*(?:\w+\s+)*\)\s*(?:can|jar)\b", RegexOptions.IgnoreCase)]
	private static partial Regex ParenCanRegex();
}
