{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongCensusRunner.cs","content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.AutoWrongCensus.Services;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs the requested subcommand over the trace file: <c>census</c> classifies every auto-wrong line
/// and prints the TSV plus the relation × site summary; <c>pairs</c> joins the P12.7 blocker census
/// with the trace. Exit 1 on a missing file, a refused set (D-029) or a malformed record.
/// </summary>
public sealed class AutoWrongCensusRunner
{
	private readonly AutoWrongCensusOptions _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly TextWriter _output;
	private readonly TextWriter _error;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">The bound CLI options.</param>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key index.</param>
	/// <param name="output">TSV sink.</param>
	/// <param name="error">Summary/diagnostics sink.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		ExactOverrideKeyIndex overrideKeys,
		TextWriter output,
		TextWriter error)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		ArgumentNullException.ThrowIfNull(output);
		ArgumentNullException.ThrowIfNull(error);
		_options = options.Value;
		_classifier = classifier;
		_overrideKeys = overrideKeys;
		_output = output;
		_error = error;
	}

	/// <summary>Runs the subcommand.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success, 1 on failure.</returns>
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		_ = cancellationToken;

		if (_options.Command == string.Empty)
		{
			Options.AutoWrongCensusUsage.Print();
			_error.WriteLine("error: unusable arguments.");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			_error.WriteLine($"error: trace file not found at '{_options.TracePath}'.");
			return 1;
		}

		if (_options.Command == Options.CommandLineArgumentParser.PairsCommand)
		{
			if (!File.Exists(_options.CensusTsvPath))
			{
				_error.WriteLine($"error: census TSV not found at '{_options.CensusTsvPath}'.");
				return 1;
			}

			return RunPairs();
		}

		return await RunCensusAsync(cancellationToken).ConfigureAwait(false);
	}

	/// <summary>The census subcommand: TSV on stdout, relation × site counts on stderr.</summary>
	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		await WriteTsvHeaderAsync().ConfigureAwait(false);
		var byRelation = new Dictionary<string, int>(StringComparer.Ordinal);
		var byRelationSite = new Dictionary<(string Relation, string Site), int>(Comparer<(string, string)>.Create(TupleComparer));
		var byMissingField = new Dictionary<string, int>(StringComparer.Ordinal);

		foreach (var line in lines)
		{
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = _classifier.Classify(line);
			await WriteTsvRowAsync(result).ConfigureAwait(false);

			byRelation[result.Relation] = byRelation.GetValueOrDefault(result.Relation) + 1;
			byRelationSite[(result.Relation, result.Site)] = byRelationSite.GetValueOrDefault((result.Relation, result.Site)) + 1;
			if (result.MissingField is not null)
			{
				byMissingField[result.MissingField] = byMissingField.GetValueOrDefault(result.MissingField) + 1;
			}
		}

		var total = byRelation.Values.Sum();
		_error.WriteLine($"set={lines[0].Set} auto-wrong lines: {total}");
		foreach (var (relation, count) in byRelation.OrderByDescending(kv => kv.Value))
		{
			var sites = byRelationSite.Where(kv => kv.Key.Relation == relation).OrderBy(kv => kv.Key.Site)
				.Select(kv => $"{kv.Key.Site}={kv.Value}").Join(", ");
			_error.WriteLine($"  {relation,-26} {count,3}  ({sites})");
		}

		if (byMissingField.Count > 0)
		{
			_error.WriteLine("missing trace fields: " + byMissingField
				.Select(kv => $"{kv.Key}={kv.Value}").Join(", "));
		}

		var other = byRelation.GetValueOrDefault(AutoWrongClassifier.RelationOther);
		if (total > 0 && other * 100 > total * 15)
		{
			_error.WriteLine($"warning: 'other' is {other * 100.0 / total:F1}% of auto-wrong lines (> 15%); see the report's found lines.");
		}

		return 0;
	}

	private static readonly Comparer<(string, string)> TupleComparer = Comparer<(string, string)>.Create((a, b) =>
		{
			var byFirst = string.CompareOrdinal(a.Item1, b.Item1);
			return byFirst != 0 ? byFirst : string.CompareOrdinal(a.Item2, b.Item2);
		});

	/// <summary>The pairs subcommand: P12.7 window compound/other rows joined with the trace.</summary>
	private int RunPairs()
	{
		var rows = File.ReadAllLines(_options.CensusTsvPath);
		if (rows.Length == 0)
		{
			_error.WriteLine("error: census TSV is empty.");
			return 1;
		}

		var header = rows[0].Split('\t');
		var col = header.ToList();
		var blockerIndex = col.IndexOf("blocker");
		var routeIndex = col.IndexOf("route");
		var holdoutIndex = col.IndexOf("holdoutId");
		var lineIndexIndex = col.IndexOf("lineIndex");
		if (blockerIndex < 0 || routeIndex < 0 || holdoutIndex < 0 || lineIndexIndex < 0)
		{
			_error.WriteLine("error: census TSV is missing the blocker/route/holdoutId/lineIndex columns.");
			return 1;
		}

		var lines = ReadTraceSync(_options.TracePath);
		if (lines is null)
		{
			return 1;
		}

		var byKey = lines.Where(l => l.Auto && !l.Correct)
			.ToDictionary(l => (l.HoldoutId, l.LineIndex), l => l, (a, b) => a);

		_output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		var written = 0;
		foreach (var row in rows.Skip(1))
		{
			var cells = row.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			if (!cells[blockerIndex].Equals("window", StringComparison.OrdinalIgnoreCase)
				|| !cells[routeIndex].Equals("compound", StringComparison.OrdinalIgnoreCase)
				&& !cells[routeIndex].Equals("other", StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}

			if (!int.TryParse(cells[lineIndexIndex], out var lineIndex) || !byKey.TryGetValue((cells[holdoutIndex], lineIndex), out var line))
			{
				_error.WriteLine($"warning: census row {cells[holdoutIndex]}#{cells[lineIndexIndex]} has no auto-wrong trace line; skipped.");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom?.ParsedName.Split(' ', StringSplitOptions.RemoveEmptyEntries)[^1] ?? string.Empty;
			_output.WriteLine($"{line.HoldoutId}\t{line.LineIndex}\t{parsedNameHead}\t{_classifier.KeyHeadPhrase(_classifier.NormalizedTokens(line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty))}\t{line.RawText}");
			written++;
		}

		_error.WriteLine($"pairs rows written: {written}");
		return 0;
	}

	private async Task WriteTsvHeaderAsync()
	{
		await _output.WriteLineAsync(
			"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
	}

	private Task WriteTsvRowAsync(ClassificationResult r) =>
		_output.WriteLineAsync(
			$"{r.HoldoutId}\t{r.LineIndex}\t{r.Set}\t{r.Relation}\t{r.Site}\t{r.OverrideKey}\t{r.AcceptedTier}\t{r.KeyTier}\t{r.AcceptedState}\t{r.KeyState}\t{r.ParsedName}\t{r.KeyHead}\t{r.AcceptedDesc}\t{r.KeyDesc}\t{r.RawText}");

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		await using var reader = new StreamReader(path);
		var lineNumber = 0;
		while (await reader.ReadLineAsync(cancellationToken) is { } line)
		{
			lineNumber++;
			if (line.Length == 0)
			{
				continue;
			}

			TraceLine? record;
			try
			{
				record = System.Text.Json.JsonSerializer.Deserialize<TraceLine>(line);
			}
			catch (System.Text.Json.JsonException ex)
			{
				_error.WriteLine($"error: {path}:{lineNumber} is not valid JSON: {ex.Message}");
				return null;
			}

			if (record is null)
			{
				_error.WriteLine($"error: {path}:{lineNumber} deserialized to null.");
				return null;
			}

			if (!record.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !record.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				_error.WriteLine($"error: refusing set '{record.Set}' at {path}:{lineNumber}; only debug and batch traces are classified (D-029).");
				return null;
			}

			lines.Add(record);
		}

		return lines;
	}

	private IReadOnlyList<TraceLine>? ReadTraceSync(string path)
	{
		var lines = new List<TraceLine>();
		foreach (var line in File.ReadLines(path))
		{
			if (line.Length == 0)
			{
				continue;
			}

			TraceLine? record;
			try
			{
				record = System.Text.Json.JsonSerializer.Deserialize<TraceLine>(line);
			}
			catch (System.Text.Json.JsonException ex)
			{
				_error.WriteLine($"error: {path} has an invalid JSON line: {ex.Message}");
				return null;
			}

			if (record is null)
			{
				_error.WriteLine($"error: {path} has a line that deserialized to null.");
				return null;
			}

			if (!record.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !record.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				_error.WriteLine($"error: refusing set '{record.Set}' at {path}; only debug and batch traces are classified (D-029).");
				return null;
			}

			lines.Add(record);
		}

		return lines;
	}
