{"path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongCensusRunner.cs","content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner. <c>census</c> classifies every auto-wrong line of one HoldoutGate trace
/// (D-029: any record whose <c>set</c> is not <c>debug</c> or <c>batch</c> is refused, exit 1);
/// <c>pairs</c> joins P12.7 blocker rows with the trace. TSV goes to the injected stdout sink,
/// the summary to stderr — the framework logs stay off stdout (the host factory pins Microsoft
/// categories at Warning).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	FdcNormalizer normalizer,
	ExactOverrideKeyIndex overrideKeys,
	System.IO.TextWriter stdout,
	System.IO.TextWriter stderr) : IAutoWrongCensusRunner
{
	private const string CensusHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	private readonly AutoWrongCensusOptions _options = options.Value;
	private readonly AutoWrongClassifier _classifier = new(normalizer, overrideKeys);

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			Options.AutoWrongCensusUsage.Print();
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			stderr.WriteLine($"trace file not found at '{_options.TracePath}'.");
			return 1;
		}

		if (_options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunCensusAsync(cancellationToken).ConfigureAwait(false);
		}

		if (_options.Command.Equals(CommandLineArgumentParser.PairsCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunPairsAsync(cancellationToken).ConfigureAwait(false);
		}

		Options.AutoWrongCensusUsage.Print();
		return 1;
	}

	/// <summary>Classifies every auto-wrong line of the trace; TSV on stdout, relation × site on stderr.</summary>
	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		stdout.WriteLine(CensusHeader);

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var counts = new Dictionary<(string Relation, string Site), int>(StringComparer.Ordinal);
		var missingFields = new Dictionary<string, int>(StringComparer.Ordinal);

		foreach (var line in autoWrong)
		{
			var result = _classifier.Classify(line);
			counts[(result.Relation, result.Site)] = counts.GetValueOrDefault((result.Relation, result.Site)) + 1;
			if (result.MissingField is not null)
			{
				missingFields[result.MissingField] = missingFields.GetValueOrDefault(result.MissingField) + 1;
			}

			stdout.WriteLine(string.Join('\t',
				result.HoldoutId,
				result.LineIndex,
				result.Set,
				result.Relation,
				result.Site,
				result.OverrideKey,
				result.AcceptedTier,
				result.KeyTier,
				result.AcceptedState,
				result.KeyState,
				result.ParsedName,
				result.KeyHead,
				result.AcceptedDesc,
				result.KeyDesc,
				result.RawText));
		}

		stdout.Flush();

		stderr.WriteLine($"auto-wrong lines: {autoWrong.Count} of {lines.Count}");
		foreach (var ((relation, site), count) in counts.OrderByDescending(kv => kv.Value))
		{
			stderr.WriteLine($"  {relation}\t{site}\t{count}");
		}

		if (missingFields.Count > 0)
		{
			stderr.WriteLine("missing trace fields:");
			foreach (var (field, count) in missingFields.OrderBy(kv => kv.Key))
			{
				stderr.WriteLine($"  {field}\t{count}");
			}
		}

		stderr.Flush();
		return 0;
	}

	/// <summary>Emits the P12.7 window compound/other rows joined with the trace's parsed names and key heads.</summary>
	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			stderr.WriteLine($"census TSV not found at '{_options.CensusTsvPath}'.");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex), l => l, (a, b) => a);
		var traceKey = lines.Select(l => (l.HoldoutId, l.LineIndex)).ToHashSet();

		stdout.WriteLine(PairsHeader);

		var emitted = 0;
		var unmatched = 0;
		var tsvLines = File.ReadLines(_options.CensusTsvPath).ToList();
		for (var i = 1; i < tsvLines.Count; i++)
		{
			cancellationToken.ThrowIfCancellationRequested();

			var fields = tsvLines[i].Split('\t');
			if (fields.Length < 20)
			{
				continue;
			}

			// census-debug.tsv column order (tools/f428-blocker-census.py): holdoutId lineIndex set stage
			// auto blocker sub keyRank keyRaw rawTop rawMargin keyL2 reason moveReason keyZone route
			// marginals allroutes parsedName rawText
			var blocker = fields[5];
			var route = fields[15];
			if (blocker != "window" || (route != "compound" && route != "other"))
			{
				continue;
			}

			var holdoutId = fields[0];
			var lineIndex = int.Parse(fields[1], System.Globalization.CultureInfo.InvariantCulture);
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var parsedNameHead = IngredientLineResolver.SingularizeToken(
				normalizer.NormalizeToTokens(line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty).FirstOrDefault() ?? string.Empty);
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty)));

			stdout.WriteLine(string.Join('\t', holdoutId, lineIndex, parsedNameHead, keyHead, line.RawText));
			emitted++;
		}

		stdout.Flush();
		stderr.WriteLine($"pairs emitted: {emitted}; trace lines: {lines.Count} ({traceKey.Count} unique); unmatched window rows: {unmatched}");
		stderr.Flush();
		return 0;
	}

	/// <summary>
	/// Reads a trace JSONL, refusing any record whose <c>set</c> is not <c>debug</c> or <c>batch</c>
	/// (D-029: no sealed read).
	/// </summary>
	/// <returns>The parsed lines, or <see langword="null"/> when the file is missing or a set was refused.</returns>
	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		if (!File.Exists(path))
		{
			stderr.WriteLine($"trace file not found at '{path}'.");
			return null;
		}

		var lines = new List<TraceLine>();
		var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);
		await using var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read);
		using var reader = new StreamReader(stream);
		while (await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false) is { } raw)
		{
			if (raw.Length == 0)
			{
				continue;
			}

			var line = JsonSerializer.Deserialize<TraceLine>(raw, options);
			if (line is null)
			{
				stderr.WriteLine($"refusing: malformed trace record on line {lines.Count + 1} of '{path}'.");
				return null;
			}

			if (!line.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !line.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				stderr.WriteLine($"refusing: record {line.HoldoutId}#{line.LineIndex} has set '{line.Set}'; only debug and batch traces are accepted (D-029).");
				return null;
			}

			lines.Add(line);
		}

		return lines;
	}
}
